(function(){function tokens(value){return String(value||"").toLowerCase().match(/[0-9a-z\u00c0-\u017f]+/g)||[]}function matches(doc,query){var hay=tokens(Object.values(doc).join(" ")).join(" ");return tokens(query).every(function(token){return hay.indexOf(token)!==-1})}function Document(){this.docs=[]}Document.prototype.add=function(doc){this.docs.push(doc)};Document.prototype.search=function(query,limit,opts){if(typeof limit==="object"){opts=limit;limit=20}limit=limit||20;opts=opts||{};var tag=opts.tag&&opts.tag.pageId;var result=this.docs.filter(function(doc){return(!tag||doc.pageId===tag)&&matches(doc,query)}).slice(0,limit).map(function(doc){return opts.enrich?{id:doc.id,doc:doc}:doc.id});return[{result:result}]};window.FlexSearch=window.FlexSearch||{};window.FlexSearch.Document=Document})();
